import sceneDocument from './scene-document';
import part1 from './scene-part-1';
import part2 from './scene-part-2';
import part3 from './scene-part-3';
import part4 from './scene-part-4';
import part5 from './scene-part-5';
import React,{useState,useEffect,createElement as h} from 'react';
async function loadScene(){
 const base=new URL('.',document.baseURI);
 const documentSource=sceneDocument,pieces=[part1.data,part2.data,part3.data,part4.data,part5.data];
 const binary=Uint8Array.from(atob(pieces.join('').replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
 const packed=await new Response(new Blob([binary]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
 const length=new DataView(packed).getUint32(0,true),meta=JSON.parse(new TextDecoder().decode(new Uint8Array(packed,4,length))),start=4+length+(4-length%4)%4;
 const buffers=meta.buffers.map(([offset,size])=>new Uint8Array(packed,start+offset,size));
 const geometries=meta.geometries.map(g=>Object.fromEntries(Object.entries(g).map(([key,index])=>[key,buffers[index]])));
 window.__AUREON_PACKAGE__={model:{geometries,nodes:meta.nodes,triangles:meta.triangles},ready:true};
 const fonts=meta.fonts.map(font=>({weight:font.weight,url:URL.createObjectURL(new Blob([buffers[font.buffer]],{type:font.mime}))}));
 const style='<style>'+fonts.map(font=>"@font-face{font-family:DM;src:url('"+font.url+"') format('truetype');font-weight:"+font.weight+";font-display:swap}").join('')+'</style>';
 return documentSource.replace('<!--AUREON_FONT_FACES-->',style).replace('<head>','<head><base href="'+base.href+'">');
}
function Aureon(){const [documentSource,setDocument]=useState(''),[error,setError]=useState('');useEffect(()=>{loadScene().then(setDocument).catch(e=>setError(e.message))},[]);return documentSource?h('iframe',{title:'AUREON — Make the Next Possible',srcDoc:documentSource,allow:'fullscreen'}):h('div',{id:'status',role:'status'},error||'ENTERING AUREON');}
export default Aureon;

