/* Adapted from the user-supplied ThreeUI GetStartedButton source. */
.shader-cta{--u:.36px;--ink:#eee5cc;--ink-hover:#fff4ce;--chev:#32230c;--chev-hover:#fff4ce;--accent:32,231,209;--ease-io:cubic-bezier(.45,0,.2,1);--ease-out:cubic-bezier(.16,.84,.3,1);display:inline-block;flex-shrink:0;vertical-align:middle;text-decoration:none}
/* ---------- the button ---------- */
.shader-cta{
  --w:calc(706 * var(--u));
  --h:calc(232 * var(--u));
  position:relative;width:var(--w);height:var(--h);
  padding:0;margin:0;border:0;background:transparent;border-radius:calc(116 * var(--u));
  cursor:pointer;appearance:none;-webkit-tap-highlight-color:transparent;outline:none;
  --m:calc(48 * var(--u));   /* canvas margin that holds the liquid-metal ring */
  isolation:isolate;
  transition:transform .18s var(--ease-out);
}
.shader-cta::after{content:"";position:absolute;inset:calc(-27 * var(--u));border-radius:calc(143 * var(--u))}  /* the ring is part of the hit area */
.shader-cta::before{content:"";position:absolute;inset:calc(-26 * var(--u));border-radius:calc(142 * var(--u));z-index:-2;pointer-events:none;
  clip-path:inset(0 calc(-400 * var(--u)) calc(-700 * var(--u)) calc(-400 * var(--u)));
  box-shadow:
    0 calc(59 * var(--u)) calc(96 * var(--u)) calc(-17 * var(--u)) rgba(0,0,0,.72),
    0 calc(182 * var(--u)) calc(88 * var(--u)) 0 rgba(0,0,0,.32),
    0 calc(16 * var(--u)) calc(44 * var(--u)) calc(-18 * var(--u)) rgba(0,0,0,0),
    0 calc(101 * var(--u)) calc(93 * var(--u)) calc(-38 * var(--u)) rgba(0,0,0,0),
    0 calc(51 * var(--u)) calc(61 * var(--u)) calc(-26 * var(--u)) rgba(0,0,0,0),
    0 calc(13 * var(--u)) calc(34 * var(--u)) calc(-12 * var(--u)) rgba(0,0,0,0);
  transition:box-shadow .35s cubic-bezier(.6,0,.35,1) .1s}
.shader-cta:focus-visible{outline:2px solid var(--cyan);outline-offset:8px}
.shader-cta:active{transform:translateY(calc(2 * var(--u))) scale(.992)}
/* Teal light cast around the crystal on hover. */
.cta-halo{position:absolute;z-index:-1;pointer-events:none;left:calc(430 * var(--u));top:calc(-44 * var(--u));width:calc(320 * var(--u));height:calc(320 * var(--u));border-radius:50%;
  background:radial-gradient(circle,rgba(var(--accent),.42) 0%,rgba(var(--accent),.16) 35%,rgba(var(--accent),0) 66%);opacity:0;
  transition:opacity .42s cubic-bezier(.6,0,.35,1)}
.cta-face{position:absolute;inset:calc(-1 * var(--m));pointer-events:none}
.cta-face canvas{position:absolute;inset:0;width:100%;height:100%;display:block}

/* label */
.cta-label{
  position:absolute;left:calc(76 * var(--u));top:50%;transform:translateY(-50%);
  font:400 calc(39 * var(--u))/1 DM,Arial,sans-serif;
  letter-spacing:calc(.2 * var(--u));white-space:pre;color:var(--ink);
  pointer-events:none;user-select:none;
  transition:color .3s var(--ease-io) .23s;
}

/* knob overlays (the crystal itself is drawn on the canvas) */
.cta-knob{position:absolute;left:calc(502 * var(--u));top:calc(28 * var(--u));width:calc(176 * var(--u));height:calc(176 * var(--u));border-radius:50%;overflow:hidden;pointer-events:none;
  -webkit-mask-image:radial-gradient(circle,#000 99%,transparent 100%);mask-image:radial-gradient(circle,#000 99%,transparent 100%)}
.cta-knob>*{position:absolute;inset:0;border-radius:50%}
/* Decorative hover hook retained from the supplied component. */
.cta-glow{width:0;height:0;inset:auto;opacity:0;transition:opacity .42s cubic-bezier(.6,0,.35,1)}
.cta-pen{overflow:visible}
.cta-pen path{fill:none;stroke:var(--chev);stroke-width:4.4;stroke-linecap:round;stroke-linejoin:round;transition:stroke .15s var(--ease-io) .15s}
.cta-pen-move{transform:translate(calc(-6 * var(--u)),0) rotate(0deg);transform-origin:68px 108px;transition:transform .5s var(--ease-io) .05s}
.cta-pen-wiggle{transform-origin:68px 108px}
.cta-scribble{stroke:var(--chev-hover);stroke-dasharray:36;stroke-dashoffset:36;transition:stroke-dashoffset .45s var(--ease-io)}
@keyframes cta-pen-write{0%{transform:rotate(-4deg) translate(0,0)}50%{transform:rotate(3deg) translate(0,calc(-1.5 * var(--u)))}100%{transform:rotate(-4deg) translate(0,0)}}

/* ---------- hover / focus ---------- */
.shader-cta:hover::before,.shader-cta:focus-visible::before,.shader-cta.is-hover::before{
  box-shadow:
    0 calc(59 * var(--u)) calc(96 * var(--u)) calc(-17 * var(--u)) rgba(0,0,0,0),
    0 calc(182 * var(--u)) calc(88 * var(--u)) 0 rgba(0,0,0,0),
    0 calc(16 * var(--u)) calc(44 * var(--u)) calc(-18 * var(--u)) rgba(0,0,0,0),
    0 calc(101 * var(--u)) calc(93 * var(--u)) calc(-38 * var(--u)) rgba(0,0,0,.12),
    0 calc(51 * var(--u)) calc(61 * var(--u)) calc(-26 * var(--u)) rgba(0,0,0,.45),
    0 calc(13 * var(--u)) calc(34 * var(--u)) calc(-12 * var(--u)) rgba(0,0,0,.98);
