.shader-cta:hover .cta-glow,.shader-cta:focus-visible .cta-glow,.shader-cta.is-hover .cta-glow{opacity:1;transition:opacity .32s cubic-bezier(.5,0,.3,1) .26s}
.shader-cta:hover .cta-pen path,.shader-cta:focus-visible .cta-pen path,.shader-cta.is-hover .cta-pen path{stroke:var(--chev-hover);transition:stroke .34s var(--ease-io) .1s}
/* the pen lifts at once, then writes a line as it moves right, then keeps a gentle scribbling motion */
.shader-cta:hover .cta-pen-move,.shader-cta:focus-visible .cta-pen-move,.shader-cta.is-hover .cta-pen-move{transform:translate(calc(20 * var(--u)),calc(-1 * var(--u))) rotate(-6deg);transition:transform .9s cubic-bezier(.5,0,.3,1) .22s}
.shader-cta:hover .cta-scribble,.shader-cta:focus-visible .cta-scribble,.shader-cta.is-hover .cta-scribble{stroke-dashoffset:0;transition:stroke-dashoffset .9s cubic-bezier(.5,0,.3,1) .22s}
.shader-cta:hover .cta-pen-wiggle,.shader-cta:focus-visible .cta-pen-wiggle,.shader-cta.is-hover .cta-pen-wiggle{animation:cta-pen-write 1.1s ease-in-out 1.1s infinite}

/* no-WebGL fallback: a flat CSS rendering of the same button */
